"\n"
"/* =====================================================================\n"
" * UI state is kept apart from the DOM. DOM attributes are only used for\n"
" * bindings (data-field / data-action / data-*key), never for source data.\n"
" * ===================================================================== */\n"
"var uiState={\n"
"  activeView:'dashboard',\n"
"  formActive:false,\n"
"  editingRuleId:null,\n"
"  pending:new Set()\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * Tiny DOM update helpers - each skips the DOM write when unchanged.\n"
" * ===================================================================== */\n"
"function setText(node,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.textContent!==next) node.textContent=next;\n"
"}\n"
"function setClass(node,cls,on){\n"
"  if(!node) return;\n"
"  if(on) node.classList.add(cls); else node.classList.remove(cls);\n"
"}\n"
"function setDisabled(node,d){\n"
"  if(!node) return;\n"
"  if(node.disabled!==!!d) node.disabled=!!d;\n"
"}\n"
"function setAttr(node,name,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.getAttribute(name)!==next) node.setAttribute(name,next);\n"
"}\n"
"function setValue(node,value){\n"
"  if(!node) return;\n"
"  var next=String(value==null?'':value);\n"
"  if(node.value!==next) node.value=next;\n"
"}\n"
"function el(tag,attrs,children){\n"
"  var n=document.createElement(tag);\n"
"  if(attrs) for(var k in attrs){\n"
"    if(!Object.prototype.hasOwnProperty.call(attrs,k)) continue;\n"
"    if(k==='class') n.className=attrs[k];\n"
"    else if(k==='text') n.textContent=attrs[k];\n"
"    else n.setAttribute(k,attrs[k]);\n"
"  }\n"
"  if(children){\n"
"    (Array.isArray(children)?children:[children]).forEach(function(c){\n"
"      if(c==null) return;\n"
"      n.appendChild(typeof c==='string'?document.createTextNode(c):c);\n"
"    });\n"
"  }\n"
"  return n;\n"
"}\n"
"function insertAt(container,node,idx){\n"
"  var kids=container.children;\n"
"  if(idx>=kids.length) container.appendChild(node);\n"
"  else container.insertBefore(node,kids[idx]);\n"
"}\n"
"\n"
"/* reconcileCollection(container, list, keyFn, attr, create, apply)\n"
" * In-place diff: existing key -> apply() in place; new key -> create one\n"
" * node; missing key -> remove one node. Order is preserved. Never wipes\n"
" * or rebuilds the container, so focus/unpersisted DOM state survives. */\n"
"function reconcileCollection(container,list,keyFn,attr,create,apply){\n"
"  var byKey={};\n"
"  list.forEach(function(it){ byKey[keyFn(it)]=it; });\n"
"  Array.prototype.slice.call(container.children).forEach(function(node){\n"
"    var k=node.getAttribute(attr);\n"
"    if(k==null||!byKey[k]) container.removeChild(node);\n"
"  });\n"
"  var kids=container.children;\n"
"  list.forEach(function(it,idx){\n"
"    var k=keyFn(it);\n"
"    var node=null;\n"
"    Array.prototype.some.call(kids,function(n){ if(n.getAttribute(attr)===k){node=n;return true;} return false; });\n"
"    if(!node){\n"
"      node=create(it);\n"
"      node.setAttribute(attr,k);\n"
"      apply(it,node);\n"
"      insertAt(container,node,idx);\n"
"    } else {\n"
"      apply(it,node);\n"
"      if(kids[idx]!==node) container.insertBefore(node,kids[idx]||null);\n"
"    }\n"
"  });\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * API + online status + toasts\n"
" * ===================================================================== */\n"
"function esc(s){\n"
"  return String(s==null?'':s)\n"
"    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')\n"
"    .replace(/\"/g,'&quot;').replace(/'/g,'&#39;');\n"
"}\n"
"function fmtBool(v){ return v===true?t('common.on'):(v===false?t('common.off'):esc(v)); }\n"
"function fmtTs(sec){ if(!sec) return '—'; return new Date(sec*1000).toLocaleTimeString(LANG); }\n"
"function apiFetch(path,opts){\n"
"  opts=opts||{};\n"
"  var ctrl=new AbortController();\n"
"  var timer=setTimeout(function(){ctrl.abort();},8000);\n"
"  var init={headers:{'Content-Type':'application/json'},signal:ctrl.signal};\n"
"  if(opts.method){ init.method=opts.method; }\n"
"  if(opts.body){ init.body=opts.body; }\n"
"  return fetch(API+path,init).then(function(r){\n"
"      clearTimeout(timer);\n"
"      return r.text().then(function(txt){\n"
"        var j=null;\n"
"        try{ j=JSON.parse(txt); }catch(e){ j=null; }\n"
"        if(!j){ throw new Error(tf('err.invalid',{0:path})); }\n"
"        if(!j.ok){ throw new Error((j.error&&j.error.code?j.error.code+': ':'')+(j.error&&j.error.message?j.error.message:'request failed')); }\n"
"        return j.data;\n"
"      });\n"
"    }).catch(function(e){\n"
"      clearTimeout(timer);\n"
"      if(e&&e.name==='AbortError') throw new Error(tf('err.timeout',{0:path}));\n"
"      throw e;\n"
"    });\n"
"}\n"
"function setOnline(b){\n"
"  statusDot.className=b?'dot ok':'dot';\n"
"  setText(statusTextEl,t(b?'chip.online':'chip.offline'));\n"
"}\n"
"function setNetLabel(txt){ setText(sysInfoEl,txt); }\n"
"function netLabelFor(s){\n"
"  if(!s||!s.network) return '';\n"
"  return s.network==='AP'||s.network==='APSTA'?('AP · '+(s.ssid||'')):'STA';\n"
"}\n"
"function showToast(type,message,duration){\n"
"  var container=document.getElementById('toast-container');\n"
"  var t0=el('div',{'class':'toast '+type,'text':message});\n"
"  container.appendChild(t0);\n"
"  setTimeout(function(){ t0.classList.add('fade-out'); },duration||3000);\n"
"  setTimeout(function(){ if(t0.parentNode) container.removeChild(t0); },(duration||3000)+300);\n"
"}\n"
"function showError(err){\n"
"  showToast('error',tf('err.toast',{0:(err&&err.message?err.message:'unknown')}));\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * Polling engine: active view only + request dedup + stale protection.\n"
" * Each view keeps: gen (stale-response check), inflight (dedup), mount/refresh/update.\n"
" * ===================================================================== */\n"
"var views={};\n"
"function makeRefresh(path,viewName){\n"
"  return function(gen){\n"
"    return apiFetch(path).then(function(data){\n"
"      if(gen===views[viewName].gen){\n"
"        setOnline(true);\n"
"        views[viewName].update(data);\n"
"      }\n"
"    });\n"
"  };\n"
"}\n"
"function runViewRefresh(v){\n"
"  if(!v||!v.refresh||v.inflight) return;\n"
"  if(v.pollable===false) return;\n"
"  if(uiState.formActive) return;\n"
"  if(typeof v.gen!=='number') v.gen=0;\n"
"  v.inflight=true;\n"
"  var gen=++v.gen;\n"
"  v.refresh(gen).then(function(){ v.inflight=false; })\n"
"    .catch(function(){ v.inflight=false; setOnline(false); });\n"
"}\n"
"function showView(name){\n"
"  uiState.activeView=name;\n"
"  try{ localStorage.setItem('tab',name); }catch(e){}\n"
"  var v=views[name];\n"
"  Array.prototype.forEach.call(navTabs.querySelectorAll('.navitem'),function(b){\n"
"    setClass(b,'active',b.getAttribute('data-tab')===name);\n"
"  });\n"
"  var host=document.getElementById('view-'+name);\n"
"  if(!host){\n"
"    host=document.createElement('div');\n"
"    host.id='view-'+name;\n"
"    host.className='content';\n"
"    main.appendChild(host);\n"
"    v.host=host;\n"
"    if(v.mount) v.mount(host);\n"
"  }\n"
"  var all=main.querySelectorAll('.content');\n"
"  Array.prototype.forEach.call(all,function(h){\n"
"    setClass(h,'active',h.id==='view-'+name);\n"
"  });\n"
"  setClass(host,'active',true);\n"
"  if(v.refresh&&v.pollable!==false) runViewRefresh(v);\n"
"}\n"
"/* Single consistent poll interval; only the active view is fetched, and a\n"
" * view that is a form (uiState.formActive) is skipped so typing survives. */\n"
"function pollTick(){\n"
"  var v=views[uiState.activeView];\n"
"  if(v&&v.refresh&&v.pollable!==false&&!uiState.formActive) runViewRefresh(v);\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * DASHBOARD view (stat cards, as the Qymera .dash-stats pattern)\n"
" * ===================================================================== */\n"
"views.dashboard={\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"page-head\"><div><h1 data-i18n=\"page.dashboard\">Panel</h1><p class=\"page-sub\" data-i18n=\"page.dashboard.sub\">Node overview</p></div></div>'+\n"
"      '<div class=\"dash-stats\">'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.status\">Status</span><span class=\"stat-value\" data-field=\"status\"><span class=\"chip ok\" data-i18n=\"chip.online\">Online</span></span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.ip\">IP</span><span class=\"stat-value\" data-field=\"ip\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.heap\">Heap</span><span class=\"stat-value\" data-field=\"heap\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.uptime\">Uptime</span><span class=\"stat-value time\" data-field=\"uptime\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.devices\">Devices</span><span class=\"stat-value\" data-field=\"device_count\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.entities\">Entities</span><span class=\"stat-value\" data-field=\"entity_count\">—</span></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var f={};\n"
"    ['status','ip','heap','uptime','device_count','entity_count'].forEach(function(n){\n"
"      f[n]=host.querySelector('[data-field=\"'+n+'\"]');\n"
"    });\n"
"    this.__f=f;\n"
"  },\n"
"  refresh:makeRefresh('/status','dashboard'),\n"
"  update:function(s){\n"
"    var f=this.__f;\n"
"    setNetLabel(netLabelFor(s));\n"
"    setText(f.ip,s.ip||'—');\n"
"    setText(f.heap,s.free_heap+' B');\n"
"    setText(f.uptime,Math.floor(s.uptime_ms/1000)+'s');\n"
"    setText(f.device_count,s.device_count);\n"
"    setText(f.entity_count,s.entity_count);\n"
"    var chip=f.status.querySelector('.chip')||f.status;\n"
"    setText(chip, t(s.online===false?'chip.offline':'chip.online'));\n"
"    setClass(chip,'ok',s.online!==false);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * DEVICES view (Qymera .device-card pattern + status dot footer)\n"
" * ===================================================================== */\n"
"function deviceCardNew(){ return el('div',{'class':'device-card','data-device-key':''}); }\n"
"function updateDeviceCard(dev,node){\n"
"  var local=(dev.role==='dashboard');\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<div class=\"device-head\">'+\n"
"      '<span class=\"chip\" data-field=\"kind\">DEVICE</span>'+\n"
"      '<span class=\"device-name\" data-field=\"name\"></span></div>'+\n"
"      '<div class=\"device-row\"><span data-field=\"id\"></span></div>'+\n"
"      '<div class=\"device-row\"><span class=\"small-note\" data-field=\"meta\"></span></div>'+\n"
"      '<div class=\"device-row\"><span data-field=\"state\"></span></div>'+\n"
"      '<div class=\"device-footer\"><span class=\"status\" data-field=\"online\"><span class=\"dot bad\"></span><span data-field=\"online_txt\"></span></span></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  setText(node.querySelector('[data-field=\"kind\"]'),local?t('status.local'):t('status.remote'));\n"
"  setClass(node.querySelector('[data-field=\"kind\"]'),'ok',!!dev.online);\n"
"  setText(node.querySelector('[data-field=\"name\"]'),esc(dev.name)||dev.device_id);\n"
"  setText(node.querySelector('[data-field=\"id\"]'),esc(dev.device_id));\n"
"  setText(node.querySelector('[data-field=\"meta\"]'),(dev.model||'')+(dev.location?(' · '+dev.location):''));\n"
"  setText(node.querySelector('[data-field=\"state\"]'),(dev.state?esc(dev.state):(dev.online?'operational':'offline')));\n"
"  var o=node.querySelector('[data-field=\"online\"]');\n"
"  var dot=o.querySelector('.dot');\n"
"  setClass(dot,'ok',!!dev.online);\n"
"  setClass(dot,'bad',!dev.online);\n"
"  setText(node.querySelector('[data-field=\"online_txt\"]'),t(dev.online?(local?'status.local':'status.remote'):'status.offline'));\n"
"}\n"
"views.devices={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\"><div><h1 data-i18n=\"page.devices\">Devices</h1><p class=\"page-sub\" data-i18n=\"page.devices.sub\"></p></div></div><div id=\"deviceList\" class=\"devices-actuator-grid\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#deviceList');\n"
"  },\n"
"  refresh:makeRefresh('/devices','devices'),\n"
"  update:function(d){\n"
"    var list=d||[];\n"
"    reconcileCollection(this.__list,list,function(x){return x.device_id;},'data-device-key',deviceCardNew,updateDeviceCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * ENTITIES view (device-card grammar; control via switch/slider)\n"
" * ===================================================================== */\n"
"function entityKind(ent){\n"
"  var caps=ent.capabilities||[];\n"
"  if(caps.indexOf('actuator.relay')>=0) return 'common.RELAY';\n"
"  if(caps.indexOf('actuator.dimmer')>=0) return 'common.DIMMER';\n"
"  return 'common.SENSOR';\n"
"}\n"
"function entityCardNew(){ return el('div',{'class':'device-card','data-entity-key':''}); }\n"
"function updateEntityCard(ent,node){\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<div class=\"device-head\">'+\n"
"      '<span class=\"chip\" data-field=\"kind\"></span>'+\n"
"      '<span class=\"device-name\" data-field=\"name\"></span></div>'+\n"
"      '<div class=\"device-row\"><span class=\"small-note\" data-field=\"key\"></span></div>'+\n"
"      '<div class=\"device-row\"><span class=\"small-note\" data-field=\"meta\"></span></div>'+\n"
"      '<div class=\"device-row\"><span data-field=\"values\"></span></div>'+\n"
"      '<div class=\"device-control\"><span data-control></span><span class=\"state-text off\" data-field=\"ctl\"></span></div>';\n"
"    node.__built=true;\n"
"  }\n"
"  setText(node.querySelector('[data-field=\"kind\"]'),t(entityKind(ent)));\n"
"  setText(node.querySelector('[data-field=\"name\"]'),esc(ent.name)||esc(ent.entity_id));\n"
"  setText(node.querySelector('[data-field=\"key\"]'),esc(ent.device_id+'/'+ent.entity_id));\n"
"  var caps=(ent.capabilities||[]).join(', ');\n"
"  setText(node.querySelector('[data-field=\"meta\"]'),(ent.type?esc(ent.type)+(ent.unit?' · '+esc(ent.unit):''):caps));\n"
"  var v=node.querySelector('[data-field=\"values\"]');\n"
"  setText(v,t('fields.current')+': '+fmtBool(ent.current)+'  ·  '+t('fields.desired')+': '+fmtBool(ent.desired));\n"
"  updateEntityControl(ent,node);\n"
"}\n"
"function updateEntityControl(ent,node){\n"
"  var key=ent.device_id+'/'+ent.entity_id;\n"
"  var caps=ent.capabilities||[];\n"
"  var isRelay=caps.indexOf('actuator.relay')>=0;\n"
"  var isDimmer=caps.indexOf('actuator.dimmer')>=0;\n"
"  var type=isRelay?'relay':(isDimmer?'dimmer':'none');\n"
"  var holder=node.querySelector('[data-control]');\n"
"  var busy=uiState.pending.has(key);\n"
"  if(node.__ctlType!==type){\n"
"    holder.innerHTML='';\n"
"    if(type==='relay'){\n"
"      node.__ctl=el('button',{'type':'button','class':'switch off','role':'switch','aria-checked':'false','data-action':'toggle','data-k':key});\n"
"      node.__ctl.appendChild(el('span',{'class':'knob'}));\n"
"      holder.appendChild(node.__ctl);\n"
"    } else if(type==='dimmer'){\n"
"      node.__ctl=el('input',{'type':'range','min':'0','max':'100','aria-label':key,'data-action':'dimmer','data-k':key});\n"
"      holder.appendChild(node.__ctl);\n"
"    } else {\n"
"      node.__ctl=null;\n"
"      holder.appendChild(el('span',{'class':'value-lg','text':fmtBool(ent.desired)}));\n"
"    }\n"
"    node.__ctlType=type;\n"
"  }\n"
"  var ctl=node.__ctl;\n"
"  var st=node.querySelector('[data-field=\"ctl\"]');\n"
"  if(type==='relay'){\n"
"    setClass(ctl,'on',ent.desired===true);\n"
"    setAttr(ctl,'aria-checked',ent.desired===true?'true':'false');\n"
"    setDisabled(ctl,busy);\n"
"    setClass(st,'on',ent.desired===true);\n"
"    setClass(st,'off',!(ent.desired===true));\n"
"    setText(st,fmtBool(ent.desired));\n"
"  } else if(type==='dimmer'){\n"
"    setDisabled(ctl,busy);\n"
"    var lv=(typeof ent.desired==='number')?ent.desired:(ent.current||0);\n"
"    if(ctl!==document.activeElement) setValue(ctl,lv);\n"
"    setText(st,(typeof ent.current==='number')?(Math.round(ent.current)+'%'):'—');\n"
"  } else {\n"
"    setText(st,ent.cmd_status||'');\n"
"  }\n"
"}\n"
"function handleToggle(t){\n"
"  if(t.disabled) return;\n"
"  var key=t.getAttribute('data-k');\n"
"  var kv=key.split('/');\n"
"  var want=(t.getAttribute('aria-checked')==='true');\n"
"  t.disabled=true; uiState.pending.add(key);\n"
"  apiFetch('/control/relay',{method:'POST',body:JSON.stringify({device_id:kv[0],entity_id:kv[1],value:!want})})\n"
"    .then(function(){ uiState.pending.delete(key); runViewRefresh(views.entities); })\n"
"    .catch(function(e){ uiState.pending.delete(key); showError(e); });\n"
"}\n"
"function handleDimmer(s){\n"
"  if(s.disabled) return;\n"
"  var key=s.getAttribute('data-k');\n"
"  var kv=key.split('/');\n"
"  s.disabled=true; uiState.pending.add(key);\n"
"  apiFetch('/control/dimmer',{method:'POST',body:JSON.stringify({device_id:kv[0],entity_id:kv[1],level:parseInt(s.value,10)})})\n"
"    .then(function(){ uiState.pending.delete(key); runViewRefresh(views.entities); })\n"
"    .catch(function(e){ uiState.pending.delete(key); showError(e); });\n"
"}\n"
"views.entities={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\"><div><h1 data-i18n=\"page.entities\">Entities</h1><p class=\"page-sub\" data-i18n=\"page.entities.sub\"></p></div></div><div id=\"entityList\" class=\"settings-grid\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#entityList');\n"
"    host.addEventListener('click',function(e){\n"
"      var t=e.target.closest?e.target.closest('[data-action=\"toggle\"]'):null;\n"
"      if(t){ e.preventDefault(); handleToggle(t); }\n"
"    });\n"
"    host.addEventListener('change',function(e){\n"
"      var s=e.target.closest?e.target.closest('[data-action=\"dimmer\"]'):null;\n"
"      if(s) handleDimmer(s);\n"
"    });\n"
"  },\n"
"  refresh:makeRefresh('/entities','entities'),\n"
"  update:function(d){\n"
"    var list=d||[];\n"
"    reconcileCollection(this.__list,list,function(x){return x.device_id+'/'+x.entity_id;},'data-entity-key',entityCardNew,updateEntityCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * RULES view (Qymera .rule-card pattern; editor is the modal overlay)\n"
" * ===================================================================== */\n"
"function ruleBrief(rule){\n"
"  if(rule.trigger&&rule.trigger.length){\n"
"    var t0=rule.trigger[0];\n"
"    if(t0&&t0.entity) return t0.entity.device_id+'/'+t0.entity.entity_id+' '+(t0.operator||'')+' '+t0.threshold;\n"
"  }\n"
"  return '—';\n"
"}\n"
"function ruleCardNew(){ return el('div',{'class':'rule-card','data-rule-key':''}); }\n"
"function updateRuleCard(rule,node){\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<div class=\"rule-head\">'+\n"
"      '<span class=\"chip\" data-field=\"statechip\">RULE</span>'+\n"
"      '<div class=\"rule-actions\">'+\n"
"      '<button class=\"btn ghost sm\" type=\"button\" data-action=\"edit-rule\"></button>'+\n"
"      '<button class=\"btn ghost sm\" type=\"button\" data-action=\"toggle-rule\"></button>'+\n"
"      '<button class=\"btn danger sm\" type=\"button\" data-action=\"del-rule\"></button>'+\n"
"      '</div></div>'+\n"
"      '<div class=\"rule-info\"><span data-i18n=\"rules.name\">Name</span><b data-field=\"name\"></b></div>'+\n"
"      '<div class=\"rule-info\"><span data-i18n=\"fields.id\">ID</span><b data-field=\"id\"></b></div>'+\n"
"      '<div class=\"rule-info\"><span data-i18n=\"rules.trig\">Trigger</span><b data-field=\"trigger\"></b></div>'+\n"
"      '<div class=\"rule-info\"><span data-i18n=\"rules.rev\">Revision</span><b data-field=\"rev\"></b></div>';\n"
"    applyI18n(node);\n"
"    node.__built=true;\n"
"  }\n"
"  setText(node.querySelector('[data-field=\"statechip\"]'),rule.enabled?t('rules.enabled'):t('rules.disabled'));\n"
"  setClass(node.querySelector('[data-field=\"statechip\"]'),'ok',!!rule.enabled);\n"
"  setText(node.querySelector('[data-field=\"name\"]'),esc(rule.name));\n"
"  setText(node.querySelector('[data-field=\"id\"]'),esc(rule.rule_id));\n"
"  setText(node.querySelector('[data-field=\"trigger\"]'),ruleBrief(rule));\n"
"  setText(node.querySelector('[data-field=\"rev\"]'),String(rule.revision||0));\n"
"  node.querySelector('[data-action=\"edit-rule\"]').setAttribute('data-rule',rule.rule_id);\n"
"  setText(node.querySelector('[data-action=\"edit-rule\"]'),t('btn.edit'));\n"
"  var tb=node.querySelector('[data-action=\"toggle-rule\"]');\n"
"  tb.setAttribute('data-rule',rule.rule_id);\n"
"  setText(tb,rule.enabled?t('btn.disable'):t('btn.enable'));\n"
"  node.querySelector('[data-action=\"del-rule\"]').setAttribute('data-rule',rule.rule_id);\n"
"  setText(node.querySelector('[data-action=\"del-rule\"]'),t('btn.delete'));\n"
"}\n"
"views.rules={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\">'+\n"
"      '<div><h1 data-i18n=\"page.rules\">Rules</h1><p class=\"page-sub\" data-i18n=\"page.rules.sub\"></p></div>'+\n"
"      '<button class=\"btn primary\" type=\"button\" data-action=\"new-rule\"><svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\" stroke-linecap=\"round\"/></svg><span data-i18n=\"btn.newRule\">New rule</span></button>'+\n"
"      '</div><div id=\"ruleList\" class=\"rule-list\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#ruleList');\n"
"    host.addEventListener('click',function(e){\n"
"      var t=null;\n"
"      if(e.target.closest) t=e.target.closest('[data-action]');\n"
"      if(!t) return;\n"
"      var a=t.getAttribute('data-action');\n"
"      if(a==='new-rule') openRuleEditor(null);\n"
"      else if(a==='edit-rule') openRuleEditor(t.getAttribute('data-rule'));\n"
"      else if(a==='toggle-rule') toggleRule(t.getAttribute('data-rule'));\n"
"      else if(a==='del-rule') deleteRule(t.getAttribute('data-rule'));\n"
"    });\n"
"  },\n"
"  refresh:makeRefresh('/rules','rules'),\n"
"  update:function(r){\n"
"    var list=r||[];\n"
"    reconcileCollection(this.__list,list,function(x){return x.rule_id;},'data-rule-key',ruleCardNew,updateRuleCard);\n"
"  }\n"
"};\n"
"function toggleRule(id){\n"
"  var card=document.querySelector('[data-rule-key=\"'+id+'\"]');\n"
"  var chip=card?card.querySelector('[data-field=\"statechip\"]').textContent:'';\n"
"  var en=(chip===t('rules.enabled'));\n"
"  apiFetch('/rules/'+encodeURIComponent(id)+(en?'/disable':'/enable'),{method:'POST'})\n"
"    .then(function(){ runViewRefresh(views.rules); })\n"
"    .catch(showError);\n"
"}\n"
"function deleteRule(id){\n"
"  if(!window.confirm(tf('rules.deleteQ',{0:id}))) return;\n"
"  apiFetch('/rules/'+encodeURIComponent(id),{method:'DELETE'})\n"
"    .then(function(){ runViewRefresh(views.rules); })\n"
"    .catch(showError);\n"
"}\n"
"\n"
"/* ---- Rule editor (Qymera modal overlay, separate from the collection DOM) ---- */\n"
"function closeRuleEditor(){\n"
"  overlayEl.classList.remove('open');\n"
"  document.getElementById('ruleFormHost').innerHTML='';\n"
"  uiState.formActive=false;\n"
"  uiState.editingRuleId=null;\n"
"  runViewRefresh(views.rules);\n"
"}\n"
"function openRuleEditor(id){\n"
"  uiState.formActive=true;\n"
"  uiState.editingRuleId=id;\n"
"  setText(document.getElementById('ruleModalTitle'),id?t('rules.titleEdit'):t('rules.titleNew'));\n"
"  overlayEl.classList.add('open');\n"
"  if(id){\n"
"    apiFetch('/rules/'+encodeURIComponent(id)).then(function(rule){\n"
"      buildRuleForm(rule);\n"
"    }).catch(function(e){ closeRuleEditor(); showError(e); });\n"
"  } else {\n"
"    buildRuleForm(null);\n"
"  }\n"
"}\n"
"function buildRuleForm(rule){\n"
"  var host=document.getElementById('ruleFormHost');\n"
"  var trig=(rule&&rule.trigger&&rule.trigger.length)?rule.trigger[0]:null;\n"
"  var actions=(rule&&rule.actions&&rule.actions.length)?rule.actions:[];\n"
"  var act=actions[0]||null;\n"
"  host.innerHTML=''+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.name\">Name</label><input id=\"rf_name\" class=\"input\" type=\"text\"></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.rule_id\">Rule ID</label><input id=\"rf_rule_id\" class=\"input\" type=\"text\"></div>'+\n"
"    '<div class=\"settings-row\" style=\"margin-bottom:12px\">'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.trg_dev\">Trigger device</label><input id=\"rf_trg_dev\" class=\"input\" type=\"text\"></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.trg_ent\">Trigger entity</label><input id=\"rf_trg_ent\" class=\"input\" type=\"text\"></div></div>'+\n"
"    '<div class=\"settings-row\" style=\"margin-bottom:12px\">'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.operator\">Operator</label><select id=\"rf_trg_op\" class=\"input\"></select></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.threshold\">Threshold</label><input id=\"rf_trg_threshold\" class=\"input\" type=\"number\"></div></div>'+\n"
"    '<div class=\"settings-row\" style=\"margin-bottom:12px\">'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.act_dev\">Action device</label><input id=\"rf_act_dev\" class=\"input\" type=\"text\"></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.act_ent\">Action entity</label><input id=\"rf_act_ent\" class=\"input\" type=\"text\"></div></div>'+\n"
"    '<div class=\"settings-row\" style=\"margin-bottom:12px\">'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.act_type\">Action type</label><select id=\"rf_act_type\" class=\"input\"></select></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.value\">Value</label><input id=\"rf_act_value\" class=\"input\" type=\"number\"></div></div>'+\n"
"    '<div class=\"settings-row\" style=\"margin-bottom:12px\">'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.cooldown\">Cooldown</label><input id=\"rf_cooldown_ms\" class=\"input\" type=\"number\"></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.priority\">Priority</label><input id=\"rf_priority\" class=\"input\" type=\"number\"></div></div>'+\n"
"    '<div class=\"field\"><label data-i18n=\"rules.max_act\">Max activations</label><input id=\"rf_max_act\" class=\"input\" type=\"number\"></div>';\n"
"  var ops=[['GT','>'],['LT','<'],['GE','≥'],['LE','≤'],['EQ','='],['NE','≠']];\n"
"  var opsSel=document.getElementById('rf_trg_op');\n"
"  ops.forEach(function(o){\n"
"    var opt=el('option',{'value':o[0],'text':o[1]});\n"
"    if(o[0]===(trig?trig.operator:null)||(!trig&&o[0]==='GT')) setAttr(opt,'selected','selected');\n"
"    opsSel.appendChild(opt);\n"
"  });\n"
"  var acts=[['SET_BOOL',t('rules.act.SET_BOOL')],['SET_LEVEL',t('rules.act.SET_LEVEL')],['SET_VALUE',t('rules.act.SET_VALUE')],['TOGGLE',t('rules.act.TOGGLE')]];\n"
"  var actsSel=document.getElementById('rf_act_type');\n"
"  acts.forEach(function(o){\n"
"    var opt=el('option',{'value':o[0],'text':o[1]});\n"
"    if(o[0]===(act?act.action:'SET_BOOL')) setAttr(opt,'selected','selected');\n"
"    actsSel.appendChild(opt);\n"
"  });\n"
"  setValue(document.getElementById('rf_name'),rule?rule.name:'');\n"
"  setValue(document.getElementById('rf_rule_id'),rule?rule.rule_id:'');\n"
"  setValue(document.getElementById('rf_trg_dev'),trig&&trig.entity?trig.entity.device_id:'dashboard');\n"
"  setValue(document.getElementById('rf_trg_ent'),trig&&trig.entity?trig.entity.entity_id:'temperature');\n"
"  setValue(document.getElementById('rf_trg_threshold'),trig?trig.threshold:30);\n"
"  setValue(document.getElementById('rf_act_dev'),act&&act.entity?act.entity.device_id:'dashboard');\n"
"  setValue(document.getElementById('rf_act_ent'),act&&act.entity?act.entity.entity_id:'fan');\n"
"  setValue(document.getElementById('rf_act_value'),act?(act.value==null?1:act.value):1);\n"
"  setValue(document.getElementById('rf_cooldown_ms'),rule?rule.cooldown_ms:60000);\n"
"  setValue(document.getElementById('rf_priority'),rule?rule.priority:10);\n"
"  setValue(document.getElementById('rf_max_act'),rule?rule.max_activations_per_hour:10);\n"
"  applyI18n(host);\n"
"}\n"
"function collectRuleBody(){\n"
"  var g=function(id){ return document.getElementById(id); };\n"
"  var body={name:g('rf_name').value};\n"
"  if(g('rf_rule_id').value) body.rule_id=g('rf_rule_id').value;\n"
"  body.trigger={entity:{device_id:g('rf_trg_dev').value,entity_id:g('rf_trg_ent').value},operator:g('rf_trg_op').value,threshold:parseFloat(g('rf_trg_threshold').value)};\n"
"  body.actions=[{entity:{device_id:g('rf_act_dev').value,entity_id:g('rf_act_ent').value},action:g('rf_act_type').value,value:parseFloat(g('rf_act_value').value)}];\n"
"  if(g('rf_cooldown_ms').value) body.cooldown_ms=parseInt(g('rf_cooldown_ms').value,10);\n"
"  if(g('rf_priority').value) body.priority=parseInt(g('rf_priority').value,10);\n"
"  if(g('rf_max_act').value) body.max_activations_per_hour=parseInt(g('rf_max_act').value,10);\n"
"  body.enabled=true;\n"
"  return body;\n"
"}\n"
"function saveRuleForm(){\n"
"  var nameEl=document.getElementById('rf_name');\n"
"  if(!nameEl||!nameEl.value.trim()){ showError(new Error(t('rules.name_req'))); return; }\n"
"  var body=collectRuleBody();\n"
"  var id=uiState.editingRuleId;\n"
"  var isNew=!id;\n"
"  apiFetch(isNew?'/rules':'/rules/'+encodeURIComponent(id),{method:isNew?'POST':'PUT',body:JSON.stringify(body)})\n"
"    .then(function(){ closeRuleEditor(); }).catch(showError);\n"
"}\n"
"\n"
"/* =====================================================================\n"
" * SKILLS view (settings-card grammar)\n"
" * ===================================================================== */\n"
"function skillCardNew(){ return el('div',{'class':'settings-card','data-skill-key':''}); }\n"
"function updateSkillCard(sk,node){\n"
"  if(!node.__built){\n"
"    node.innerHTML=''+\n"
"      '<div class=\"settings-card-head\">'+\n"
"      '<div><span class=\"eyebrow\" data-field=\"ver\"></span><h3 data-field=\"name\"></h3></div>'+\n"
"      '<span class=\"chip\" data-i18n=\"common.SENSOR\">SKILL</span></div>'+\n"
"      '<div class=\"kv\"><span data-i18n=\"fields.state\">State</span><b data-field=\"desc\"></b></div>'+\n"
"      '<div class=\"kv\"><span data-i18n=\"fields.schema\">Schema</span><b data-field=\"schema\"></b></div>'+\n"
"      '<div class=\"kv\"><span data-i18n=\"fields.perms\">Perms</span><b data-field=\"perms\"></b></div>';\n"
"    applyI18n(node);\n"
"    node.__built=true;\n"
"  }\n"
"  setText(node.querySelector('[data-field=\"ver\"]'),'v'+sk.version);\n"
"  setText(node.querySelector('[data-field=\"name\"]'),esc(sk.name));\n"
"  setText(node.querySelector('[data-field=\"desc\"]'),sk.description||'');\n"
"  setText(node.querySelector('[data-field=\"schema\"]'),sk.schema_id||'');\n"
"  var perms='';\n"
"  if(sk.permissions&1) perms+='READ ';\n"
"  if(sk.permissions&2) perms+='CONTROL ';\n"
"  if(sk.permissions&4) perms+='RULE_READ ';\n"
"  if(sk.permissions&8) perms+='RULE_WRITE ';\n"
"  setText(node.querySelector('[data-field=\"perms\"]'),perms||'—');\n"
"}\n"
"views.skills={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\"><div><h1 data-i18n=\"page.skills\">Skills</h1><p class=\"page-sub\" data-i18n=\"page.skills.sub\"></p></div></div><div id=\"skillList\" class=\"settings-grid\"></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#skillList');\n"
"  },\n"
"  refresh:makeRefresh('/skills','skills'),\n"
"  update:function(sk){\n"
"    var list=sk||[];\n"
"    reconcileCollection(this.__list,list,function(x){return x.name;},'data-skill-key',skillCardNew,updateSkillCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * AI view (assistant): configure the upstream and chat through\n"
" * POST /api/v1/ai/chat. Long turns are allowed (the device runs each tool\n"
" * call through the model), so chat uses its own ~3 min timeout instead of\n"
" * the 8 s apiFetch one. Not polled.\n"
" * ===================================================================== */\n"
"function aiEndIsErr(e){ return e==='malformed'||e==='provider_error'||e==='timeout'||e==='error'; }\n"
"function aiParseOutcome(o){\n"
"  if(!o) return [];\n"
"  var res=[];\n"
"  String(o).split('\\n').forEach(function(l){\n"
"    if(!l) return;\n"
"    var m=/^\\[tool:([^\\]]+):(ok|error)\\]\\s?([\\s\\S]*)$/.exec(l);\n"
"    res.push(m?{st:m[2], text:'['+m[1]+':'+m[2]+'] '+(m[3]||'')}:{st:'', text:l});\n"
"  });\n"
"  return res;\n"
"}\n"
"views.ai={\n"
"  pollable:false,\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"page-head\"><div><h1 data-i18n=\"page.ai\">Asistente IA</h1><p class=\"page-sub\" data-i18n=\"page.ai.sub\"></p></div></div>'+\n"
"      '<div class=\"settings-grid\" id=\"aiCfgGrid\">'+\n"
"      '<div class=\"settings-card\"><div class=\"settings-card-head\"><div><span class=\"eyebrow\" data-i18n=\"ai.mode\">Modo</span><h3 data-i18n=\"ai.config\">Asistente IA</h3></div><span class=\"chip\" id=\"aiModeChip\">—</span></div>'+\n"
"      '<p class=\"small-note\" data-i18n=\"ai.config_hint\"></p>'+\n"
"      '<div class=\"field\"><label data-i18n=\"ai.mode\">Modo</label><select id=\"aiMode\" class=\"input\">'+\n"
"      '<option value=\"none\" data-i18n=\"ai.mode_none\">Sin modelo</option>'+\n"
"      '<option value=\"local\" data-i18n=\"ai.mode_local\">Local</option>'+\n"
"      '<option value=\"remote\" data-i18n=\"ai.mode_remote\">Remoto</option>'+\n"
"      '<option value=\"hybrid\" data-i18n=\"ai.mode_hybrid\">Híbrido</option></select></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"ai.endpoint\">Endpoint</label><input id=\"aiEndpoint\" class=\"input\" data-i18n-ph=\"ai.endpoint_ph\" placeholder=\"http://192.168.1.16:11434\"></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"ai.key\">Clave API</label><input id=\"aiKey\" class=\"input\" type=\"password\" data-i18n-ph=\"ai.key_ph\"></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"ai.model\">Modelo</label><input id=\"aiModel\" class=\"input\" data-i18n-ph=\"ai.model_ph\" placeholder=\"qwen3.5:2b\"></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"ai.timeout\">Timeout</label><input id=\"aiTimeout\" class=\"input\" type=\"number\" value=\"60000\" min=\"1000\" max=\"120000\"></div>'+\n"
"      '<div class=\"btn-row\"><button id=\"aiSave\" class=\"btn primary\" type=\"button\"><span data-i18n=\"ai.save\">Guardar y reiniciar</span></button><span id=\"aiCfgMsg\" class=\"small-note\"></span></div>'+\n"
"      '</div></div>'+\n"
"      '<div class=\"settings-card\" style=\"margin-top:14px\"><div class=\"settings-card-head\"><div><span class=\"eyebrow\" data-i18n=\"ai.chat\">Chat</span><h3 data-i18n=\"page.ai\">Asistente IA</h3></div></div>'+\n"
"      '<div id=\"aiChatList\" class=\"chat-list\"></div>'+\n"
"      '<div class=\"chat-input-row\"><input id=\"aiPrompt\" class=\"input\" maxlength=\"2000\" data-i18n-ph=\"ai.prompt_ph\" placeholder=\"Describe qué quieres hacer...\"><button id=\"aiSend\" class=\"btn primary\" type=\"button\"><span data-i18n=\"ai.send\">Enviar</span></button></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var modeSel=host.querySelector('#aiMode');\n"
"    var epEl=host.querySelector('#aiEndpoint');\n"
"    var keyEl=host.querySelector('#aiKey');\n"
"    var modelEl=host.querySelector('#aiModel');\n"
"    var timeoutEl=host.querySelector('#aiTimeout');\n"
"    var saveBtn=host.querySelector('#aiSave');\n"
"    var cfgMsg=host.querySelector('#aiCfgMsg');\n"
"    var modeChip=host.querySelector('#aiModeChip');\n"
"    var list=host.querySelector('#aiChatList');\n"
"    var promptEl=host.querySelector('#aiPrompt');\n"
"    var sendBtn=host.querySelector('#aiSend');\n"
"    var busy=false;\n"
"    list.appendChild(el('div',{'class':'chat-step','text':t('ai.empty')}));\n"
"    /* Prefill current mode from /status (best-effort, no toast on failure). */\n"
"    fetch(API+'/status',{headers:{'Content-Type':'application/json'}}).then(function(r){\n"
"      return r.json();\n"
"    }).then(function(j){\n"
"      if(j&&j.ok&&j.data){\n"
"        var m=j.data.ai_mode||'none';\n"
"        if(['none','local','remote','hybrid'].indexOf(m)>=0) modeSel.value=m;\n"
"        setText(modeChip,t('ai.mode_'+m));\n"
"      }\n"
"    }).catch(function(){});\n"
"    var aiRenderError=function(wait,msg){\n"
"      wait.appendChild(el('div',{'class':'chat-bubble err','text':msg}));\n"
"      list.scrollTop=list.scrollHeight;\n"
"    };\n"
"    var aiRenderTurn=function(wait,data){\n"
"      var bubble=el('div',{'class':'chat-bubble'});\n"
"      var head=el('div',{'class':'chat-head','text':tf('ai.steps',{0:data.tool_calls})+' · '});\n"
"      head.appendChild(el('span',{'class':'chip '+(aiEndIsErr(data.ended)?'danger':'ok'),'text':t('ai.end.'+(data.ended||'error'))}));\n"
"      bubble.appendChild(head);\n"
"      var steps=aiParseOutcome(data.outcome);\n"
"      if(steps.length){\n"
"        var tl=el('div',{'class':'chat-tools'});\n"
"        steps.forEach(function(st){ tl.appendChild(el('div',{'class':'chat-step '+st.st,'text':st.text})); });\n"
"        bubble.appendChild(tl);\n"
"      }\n"
"      var ft=(data.final&&data.final.text)?data.final.text:null;\n"
"      if(ft) bubble.appendChild(el('p',{'class':'chat-final','text':ft}));\n"
"      wait.appendChild(bubble);\n"
"      list.scrollTop=list.scrollHeight;\n"
"    };\n"
"    var chatSend=function(){\n"
"      var p=(promptEl.value||'').trim();\n"
"      if(!p){ showError(new Error(t('ai.prompt_req'))); return; }\n"
"      if(busy) return;\n"
"      busy=true;\n"
"      setDisabled(sendBtn,true);\n"
"      promptEl.value='';\n"
"      var urow=el('div',{'class':'chat-row user'});\n"
"      urow.appendChild(el('div',{'class':'chat-meta','text':t('ai.you')}));\n"
"      urow.appendChild(el('div',{'class':'chat-bubble','text':p}));\n"
"      list.appendChild(urow);\n"
"      var wait=el('div',{'class':'chat-row ai'});\n"
"      wait.appendChild(el('div',{'class':'chat-meta','text':t('ai.assistant')}));\n"
"      wait.appendChild(el('div',{'class':'chat-bubble','text':t('ai.thinking')}));\n"
"      list.appendChild(wait);\n"
"      list.scrollTop=list.scrollHeight;\n"
"      var ctrl=new AbortController();\n"
"      var timer=setTimeout(function(){ ctrl.abort(); },180000);\n"
"      fetch(API+'/ai/chat',{method:'POST',signal:ctrl.signal,\n"
"        headers:{'Content-Type':'application/json'},\n"
"        body:JSON.stringify({prompt:p,permission_mask:0x0F})})\n"
"        .then(function(r){ clearTimeout(timer); return r.text(); })\n"
"        .then(function(txt){\n"
"          busy=false; setDisabled(sendBtn,false);\n"
"          var j=null; try{ j=JSON.parse(txt); }catch(e){ j=null; }\n"
"          if(!j||!j.ok){ aiRenderError(wait,(j&&j.error&&j.error.message)?(j.error.code?j.error.code+': ':'')+j.error.message:'request failed'); return; }\n"
"          aiRenderTurn(wait,j.data);\n"
"        })\n"
"        .catch(function(e){\n"
"          clearTimeout(timer); busy=false; setDisabled(sendBtn,false);\n"
"          aiRenderError(wait,(e&&e.name==='AbortError')?t('ai.timeout_msg'):(e&&e.message?e.message:String(e)));\n"
"        });\n"
"    };\n"
"    sendBtn.addEventListener('click',chatSend);\n"
"    promptEl.addEventListener('keydown',function(e){\n"
"      if(e.key==='Enter') e.preventDefault();\n"
"      if(e.key==='Enter'&&!e.shiftKey){ chatSend(); }\n"
"    });\n"
"    saveBtn.addEventListener('click',function(){\n"
"      setDisabled(saveBtn,true);\n"
"      var body={\n"
"        mode:modeSel.value,\n"
"        local_endpoint:epEl.value.trim()||'',\n"
"        local_api_key:keyEl.value.trim()||'',\n"
"        default_model:modelEl.value.trim()||'',\n"
"        default_timeout_ms:parseInt(timeoutEl.value,10)||60000\n"
"      };\n"
"      apiFetch('/ai/config',{method:'POST',body:JSON.stringify(body)})\n"
"        .then(function(){ cfgMsg.textContent=tf('ai.saved',{0:body.mode}); setOnline(false); })\n"
"        .catch(function(e){ cfgMsg.textContent=t('ai.save_failed'); setDisabled(saveBtn,false); showError(e); });\n"
"    });\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * LOGS view (log-panel grammar)\n"
" * ===================================================================== */\n"
"function logKey(e){\n"
"  var ts=(typeof e.ts==='number')?e.ts:(e.timestamp?e.timestamp.seconds:0);\n"
"  return ts+':'+(e.source||'')+':'+(e.msg||'');\n"
"}\n"
"function logCardNew(){ return el('div',{'class':'log-entry','data-log-key':''}); }\n"
"function updateLogCard(e,node){\n"
"  var lvl=String(e.level||e.layer||'').toLowerCase();\n"
"  var lcls='inf';\n"
"  if(lvl==='warn'||lvl==='warning') lcls='wrn';\n"
"  if(lvl==='err'||lvl==='error') lcls='err';\n"
"  var ts=(typeof e.ts==='number')?e.ts:(e.timestamp?e.timestamp.seconds:0);\n"
"  if(!node.firstChild){\n"
"    node.appendChild(el('span',{'class':'t','text':'['+fmtTs(ts)+']'}));\n"
"    node.appendChild(el('span',{'class':'l '+lcls,'text':(e.source||'').slice(0,6)+' '}));\n"
"    node.appendChild(el('span',{'class':'m','text':e.msg||''}));\n"
"  } else {\n"
"    var t0=node.querySelector('.t'); setText(t0,'['+fmtTs(ts)+']');\n"
"    var l=node.querySelector('.l'); setText(l,(e.source||'').slice(0,6)+' ');\n"
"    setClass(l,'inf',lcls==='inf'); setClass(l,'wrn',lcls==='wrn'); setClass(l,'err',lcls==='err');\n"
"    setText(node.querySelector('.m'),e.msg||'');\n"
"  }\n"
"}\n"
"views.logs={\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\"><div><h1 data-i18n=\"page.logs\">Logs</h1><p class=\"page-sub\" data-i18n=\"page.logs.sub\"></p></div></div>'+\n"
"      '<div class=\"log-status\" id=\"logStatus\" data-field=\"lstatus\"></div><div class=\"log-grid\"><div class=\"log-panel\"><h3 data-i18n=\"page.logs\">Logs</h3><div id=\"logList\"></div></div></div>';\n"
"    applyI18n(host);\n"
"    this.__list=host.querySelector('#logList');\n"
"    this.__status=host.querySelector('[data-field=\"lstatus\"]');\n"
"  },\n"
"  refresh:makeRefresh('/logs','logs'),\n"
"  update:function(l){\n"
"    var list=(l||[]).slice(0,50);\n"
"    var st=this.__status;\n"
"    if(!list.length){ setText(st,t('log.empty')); setClass(st,'error',false); setClass(st,'ok',false); }\n"
"    else { setText(st,tf('log.updated',{0:fmtTs(Math.floor(Date.now()/1000)),1:list.length})); setClass(st,'ok',true); setClass(st,'error',false); }\n"
"    reconcileCollection(this.__list,list,logKey,'data-log-key',logCardNew,updateLogCard);\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * SYSTEM view (stat cards)\n"
" * ===================================================================== */\n"
"views.system={\n"
"  mount:function(host){\n"
"    host.innerHTML=\n"
"      '<div class=\"page-head\"><div><h1 data-i18n=\"page.system\">System</h1><p class=\"page-sub\" data-i18n=\"page.system.sub\"></p></div></div>'+\n"
"      '<div class=\"dash-stats\">'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.ip\">IP</span><span class=\"stat-value\" data-field=\"ip\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.heap\">Heap</span><span class=\"stat-value\" data-field=\"heap\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"stat.uptime\">Uptime</span><span class=\"stat-value time\" data-field=\"uptime\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"net.ssid\">SSID</span><span class=\"stat-value\" data-field=\"ssid\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"fields.state\">Mode</span><span class=\"stat-value\" data-field=\"net\">—</span></div>'+\n"
"      '<div class=\"stat-card\"><span class=\"stat-label\" data-i18n=\"fields.model\">Build</span><span class=\"stat-value\" data-field=\"build\">ESP32 Dashboard</span></div>'+\n"
"      '</div>';\n"
"    applyI18n(host);\n"
"    var f={};\n"
"    ['ip','heap','uptime','ssid','net','build'].forEach(function(n){\n"
"      f[n]=host.querySelector('[data-field=\"'+n+'\"]');\n"
"    });\n"
"    this.__f=f;\n"
"  },\n"
"  refresh:makeRefresh('/status','system'),\n"
"  update:function(s){\n"
"    var f=this.__f;\n"
"    setNetLabel(netLabelFor(s));\n"
"    setText(f.ip,s.ip||'—');\n"
"    setText(f.heap,s.free_heap+' B');\n"
"    setText(f.uptime,Math.floor(s.uptime_ms/1000)+'s');\n"
"    setText(f.ssid,s.ssid||'—');\n"
"    setText(f.net,String(s.network||'—'));\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * NETWORK view (settings-card grammar; explicit scan, never auto-\n"
" * refreshed, so the setup form keeps focus untouched by polling)\n"
" * ===================================================================== */\n"
"var scanCache=[];\n"
"views.network={\n"
"  pollable:false,\n"
"  mount:function(host){\n"
"    host.innerHTML='<div class=\"page-head\"><div><h1 data-i18n=\"page.network\">Network</h1><p class=\"page-sub\" data-i18n=\"page.network.sub\"></p></div></div>'+\n"
"      '<div class=\"settings-grid\">'+\n"
"      '<div class=\"settings-card settings-general\"><p class=\"small-note\" data-i18n=\"net.hint\">Hint</p></div>'+\n"
"      '<div class=\"settings-card\"><h3 data-i18n=\"net.scan\">Scan</h3>'+\n"
"      '<div class=\"btn-row\"><button class=\"btn ghost sm\" type=\"button\" id=\"scanBtn\"><span data-i18n=\"net.scan_btn\">Scan for networks</span></button></div>'+\n"
"      '<div id=\"scanList\" style=\"margin-top:8px\"></div></div>'+\n"
"      '<div class=\"settings-card\"><h3 data-i18n=\"net.connect\">Connect</h3>'+\n"
"      '<div class=\"field\"><label data-i18n=\"net.ssid\">SSID</label><input id=\"netSsid\" class=\"input\" list=\"scanOpts\" data-i18n-ph=\"net.ssid_ph\" placeholder=\"Network name\"></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"net.pass\">Password</label><input id=\"netPassword\" class=\"input\" type=\"password\" data-i18n-ph=\"net.pass_ph\" placeholder=\"WiFi password\"></div>'+\n"
"      '<div class=\"settings-row\">'+\n"
"      '<div class=\"field\"><label data-i18n=\"net.udp_disc\">UDP Discovery</label><input id=\"netUdpDiscovery\" class=\"input\" type=\"number\" value=\"13345\" min=\"1\" placeholder=\"13345\"></div>'+\n"
"      '<div class=\"field\"><label data-i18n=\"net.udp_ctrl\">UDP Control</label><input id=\"netUdpControl\" class=\"input\" type=\"number\" value=\"13346\" min=\"1\" placeholder=\"13346\"></div></div>'+\n"
"      '<label class=\"check\"><input type=\"checkbox\" id=\"netEnable\" checked><span data-i18n=\"net.sta_enable\">Enable STA (connect on boot)</span></label>'+\n"
"      '<div class=\"btn-row\"><button class=\"btn primary\" type=\"button\" id=\"connectBtn\"><span data-i18n=\"net.save\">Save & Reboot</span></button><span id=\"netMsg\" class=\"small-note\"></span></div>'+\n"
"      '</div></div>'+\n"
"      '<datalist id=\"scanOpts\"></datalist>';\n"
"    applyI18n(host);\n"
"    var scanBtn=document.getElementById('scanBtn');\n"
"    var connectBtn=document.getElementById('connectBtn');\n"
"    var msg=document.getElementById('netMsg');\n"
"    var scanList=document.getElementById('scanList');\n"
"    var scanOpts=document.getElementById('scanOpts');\n"
"    var ssidEl=document.getElementById('netSsid');\n"
"    var passEl=document.getElementById('netPassword');\n"
"    var enableEl=document.getElementById('netEnable');\n"
"    var renderScanList=function(nets){\n"
"      if(!nets.length){ scanList.innerHTML='<div class=\"empty sm\" data-i18n=\"net.no_nets\">No networks found. Try scanning again.</div>'; applyI18n(scanList); return; }\n"
"      scanList.innerHTML='<p class=\"small-note\" style=\"margin-bottom:6px\" data-i18n=\"net.click_ssid\">Click an SSID to select it:</p>'+\n"
"        '<div class=\"scan-row\">'+nets.map(function(n){\n"
"          return '<button type=\"button\" class=\"btn ghost sm\" style=\"width:auto\" data-ssid=\"'+esc(n.ssid)+'\">'+esc(n.ssid)+' ('+esc(n.rssi)+' dBm)</button>';\n"
"        }).join('')+'</div>';\n"
"      applyI18n(scanList);\n"
"      scanOpts.innerHTML=nets.map(function(n){ return '<option value=\"'+esc(n.ssid)+'\">'; }).join('');\n"
"    };\n"
"    scanList.addEventListener('click',function(e){\n"
"      var b=e.target.closest?e.target.closest('[data-ssid]'):null;\n"
"      if(b) setValue(ssidEl,b.getAttribute('data-ssid'));\n"
"    });\n"
"    scanBtn.addEventListener('click',function(){\n"
"      msg.textContent=t('net.scanning');\n"
"      setDisabled(scanBtn,true);\n"
"      apiFetch('/wifi/scan').then(function(nets){\n"
"        scanCache=nets||[];\n"
"        renderScanList(scanCache);\n"
"        msg.textContent=tf('net.found',{0:scanCache.length});\n"
"        setDisabled(scanBtn,false);\n"
"      }).catch(function(){ msg.textContent=t('net.scan_failed'); setDisabled(scanBtn,false); });\n"
"    });\n"
"    connectBtn.addEventListener('click',function(){\n"
"      var ssid=ssidEl.value.trim();\n"
"      if(!ssid){ msg.textContent=t('net.ssid_req'); return; }\n"
"      var password=passEl.value;\n"
"      var enable=enableEl.checked;\n"
"      var udpDiscovery=document.getElementById('netUdpDiscovery').value||'13345';\n"
"      var udpControl=document.getElementById('netUdpControl').value||'13346';\n"
"      msg.textContent=t('btn.save');\n"
"      setDisabled(connectBtn,true);\n"
"      apiFetch('/wifi/connect',{method:'POST',body:JSON.stringify({ssid:ssid,password:password,enabled:enable,udp_discovery_port:Number(udpDiscovery),udp_control_port:Number(udpControl)})})\n"
"        .then(function(){ msg.textContent=t('net.saved'); setTimeout(function(){ setOnline(false); },500); })\n"
"        .catch(function(){ msg.textContent=t('net.save_failed'); setDisabled(connectBtn,false); });\n"
"    });\n"
"  }\n"
"};\n"
"\n"
"/* =====================================================================\n"
" * Wiring (runs once after all views are defined).\n"
" * ===================================================================== */\n"
"navTabs.addEventListener('click',function(e){\n"
"  var b=e.target.closest?e.target.closest('.navitem'):null;\n"
"  if(!b||!b.getAttribute('data-tab')) return;\n"
"  e.preventDefault();\n"
"  showView(b.getAttribute('data-tab'));\n"
"});\n"
"overlayEl.addEventListener('click',function(e){\n"
"  if(e.target===overlayEl){ closeRuleEditor(); return; }\n"
"});\n"
"document.getElementById('overlayClose').addEventListener('click',closeRuleEditor);\n"
"document.getElementById('overlayCancel').addEventListener('click',closeRuleEditor);\n"
"document.getElementById('overlaySave').addEventListener('click',saveRuleForm);\n"
"\n"
"/* Boot: theme, language and last tab are restored exactly like Qymera. */\n"
"var savedBg=null;\n"
"try{ savedBg=localStorage.getItem('bgColor'); }catch(e){}\n"
"if(savedBg) setBackground(savedBg);\n"
"setLang(LANG);\n"
"buildNav();\n"
"setOnline(false);\n"
"var validTabs=['dashboard','devices','entities','rules','skills','ai','system','network','logs'];\n"
"var savedTab=null;\n"
"try{ savedTab=localStorage.getItem('tab'); }catch(e){}\n"
"if(validTabs.indexOf(savedTab)===-1) savedTab='dashboard';\n"
"showView(savedTab);\n"
"setInterval(pollTick,10000);\n"
"</script>\n"
"</body>\n"
"</html>\n";
